function SelectedMovie({ selectedId, handleCloseMovie }) {
  const [movie, setMovie] = useState({});

  const {
    Title: title,
    Year: year,
    Poster: poster,
    Runtime: runtime,
    imdbRating,
    Plot: plot,
    Released: released,
    Actors: actors,
    Director: director,
    Genre: genre,
  } = movie; //把movie里的Title取出值存到title里

  useEffect(function () {
    async function fetchById() {
      const res = await fetch(
        `http://www.omdbapi.com/?apikey=${key}&i=${selectedId}`
      );
      const data = await res.json();
      console.log(data);
      setMovie(data);
    }
    fetchById();
  }, []);

  return (
